// The contracts registry: every on-chain address Gully Labs uses, per chain, in one place. It feeds
//   - the public JSON at /.well-known/contracts.json (server/discovery.mjs),
//   - the docs page /contracts (src/docs/pages/ContractsDocs.tsx),
//   - /llms-full.txt, and
//   - the name-tag drafts in ops/EXPLORER-SUBMISSIONS.md.
//
// Rules: an address is here only if it is written in a file in one of our repos, and `source` names that file
// ("<repo>:<path>", the same notation as features.ts: 'website' is this repo, anything else is a sibling repo under
// PROJECTS). npm run test:contracts re-reads every source and fails if the address is not in it. Never add an
// address from memory, an explorer or a chat; if no file has it, it does not belong here.
//
// The block between BEGIN ENTRIES and END ENTRIES is written by `node scripts/gen-contracts.mjs` (it reads the
// source files and asks Sourcify which addresses are verified). Edit the generator's inputs, not the block.

export type ContractOwner = 'gully-labs' | 'third-party'

export interface ChainInfo {
  id: number
  name: string
  /** Block explorer base URL, no trailing slash. */
  explorer: string
  /** Which explorer software it runs, for the name-tag drafts. */
  family: 'etherscan' | 'blockscout' | 'unknown'
}

/** The chains the registry covers, from the explorers each repo itself lists. */
